 */
निर्यात async फ़ंक्शन getDailySentence(): Promise<SentenceItem | शून्य> {
  स्थिरांक सभी = प्रतीक्षा करें लोडसेंटेंस();
  यदि (सभी लंबाई === 0) शून्य लौटें;

  स्थिरांक आज = नई तिथि();
  constdayOfYear = Math.floor(
    (आज.गेटटाइम() - नई तिथि(आज.गेटफुलईयर(), 0, 0).गेटटाइम()) / 1000 / 60 / 60 / 24
  );
  स्थिरांक सूचकांक = Math.abs((dayOfYear * 97 + आज.getFullYear()) % all.length);
  सभी[सूचकांक] लौटाएं || सभी[0];
}

